class _PosixPipeWriter:
    """Bound request writes too: a live child can stop draining its stdin."""
    def __init__(self, stream):
        self.fd = stream.fileno()
        os.set_blocking(self.fd, False)

    def write_all(self, payload, timeout=10.):
        deadline = time.monotonic() + timeout
        pending = memoryview(payload)
        while pending:
            remaining = deadline - time.monotonic()
            if remaining <= 0. or not select.select([], [self.fd], [], remaining)[1]:
                raise RuntimeError('Rust engine request write timed out')
            try:
                count = os.write(self.fd, pending)
            except BlockingIOError:
                continue
            if count <= 0:
                raise RuntimeError('Rust engine request pipe closed')
            pending = pending[count:]

